"use strict";
// The place where the program stands is told by a function of this package from here on.
const told = [];
const own = process.cwd;
process.cwd = () => told[told.push(own()) - 1];
const here = process.cwd();
module.exports = { ok: [here === own(), told.length, process.cwd.length, process.cwd === own].join() };
